\title{The Siegel--Weil Identity for the $E_8$ Theta Series:\\
M\"obius Inversion, Closed Forms, and the Eigenform Boundary}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\begin{abstract}
The Siegel--Weil identity in rank $8$ asserts that the theta series of the even
unimodular lattice $E_8$ coincides with the weight-$4$ Eisenstein series $E_4$.
On Fourier coefficients this is the arithmetic statement
$r(n) = 240\,\sig_3(n)$, where $\sig_3(n) = \sum_{d\mid n} d^3$ and $r(n)$ counts
the vectors of $E_8$ of squared length $2n$. Taking this identity as a starting
point, we develop the arithmetic structure of the coefficient system
$240\,\sig_3$ and, more generally, of the divisor-power sum $\sig_s$, the
coefficient system of the weight-$(s+1)$ Eisenstein series. We establish three
independent structural results: a division-free closed form
$\sig_s(p^r)(p^s-1) = p^{s(r+1)}-1$; a M\"obius inversion
$n^s = \sum_{de=n}\mu(d)\sig_s(e)$ recovering pure powers from the divisor sum,
with its transport $\sum_{de=n}\mu(d)r(e)=240\,n^3$ to the $E_8$ counts; and an
eigenform boundary result, the Hecke correction $\sig_s(p^2)+p^s=\sig_s(p)^2$
and the strict inequality $\sig_s(p^2)<\sig_s(p)^2$. All results are corroborated
against the known low-order $E_8$ vector counts $240,2160,6720,17520,30240$.
\end{abstract}
\maketitle

\section{Introduction}

\subsection{The $E_8$ lattice and its theta series}
A lattice $L \subset \R^n$ is \emph{even} if $\langle x,x\rangle \in 2\Z$ for all
$x \in L$, and \emph{unimodular} if it equals its own dual. Even unimodular
lattices exist only in dimensions divisible by $8$; in dimension exactly $8$
there is, up to isometry, a unique one, the $E_8$ lattice --- the densest sphere
packing in eight-dimensional space. Its \emph{theta series} is
\[
\theta_L(\tau) = \sum_{x \in L} q^{\langle x,x\rangle/2}, \qquad q = e^{2\pi i \tau},
\]
a modular form of weight $4$ for $\mathrm{SL}_2(\Z)$, whose $q^n$-coefficient is
the number of lattice vectors of squared length $2n$.

\subsection{The Siegel--Weil identity in rank 8}
The space of weight-$4$ modular forms for $\mathrm{SL}_2(\Z)$ is one-dimensional,
spanned by
\[
E_4(\tau) = 1 + 240 \sum_{n=1}^{\infty} \sig_3(n)\, q^n .
\]
Since $\theta_L$ has constant term $1$ and lies in this one-dimensional space, it
equals $E_4$. Comparing coefficients gives the foundational special case of the
Siegel--Weil formula:
\begin{equation}\label{eq:star}
r(n) = 240\,\sig_3(n), \qquad \sig_3(n) = \sum_{d\mid n} d^3. \tag{$\star$}
\end{equation}
We take \eqref{eq:star} as our starting point and investigate the arithmetic
character of the coefficient system it produces, working with the general
divisor-power sum $\sig_s(n) = \sum_{d\mid n} d^s$, the coefficient system of the
weight-$(s+1)$ Eisenstein series ($s=3$ specializing to $E_8$).

\section{Prime-power structure and the division-free closed form}

\begin{lemma}[Geometric form on prime powers]\label{lem:geom}
For a prime $p$ and integers $s,r\ge 0$,
\[
\sig_s(p^r) = \sum_{i=0}^{r} p^{s i} = 1 + p^s + p^{2s} + \cdots + p^{rs}.
\]
\end{lemma}
\begin{proof}
The divisors of $p^r$ are $1,p,\dots,p^r$; summing their $s$-th powers gives
$\sum_{i=0}^r (p^i)^s = \sum_{i=0}^r p^{si}$.
\end{proof}

\begin{corollary}\label{cor:prime}
For a prime $p$, $\sig_s(p) = 1 + p^s$.
\end{corollary}

\begin{theorem}[Division-free Euler-factor closed form]\label{thm:closed}
For a prime $p$ and integers $s,r\ge 0$,
\[
\sig_s(p^r)\,\bigl(p^s - 1\bigr) = p^{s(r+1)} - 1.
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:geom}, $\sig_s(p^r) = \sum_{i=0}^r (p^s)^i$. The identity
$\bigl(\sum_{i=0}^r x^i\bigr)(x-1) = x^{r+1}-1$ with $x=p^s$ gives
$\sig_s(p^r)(p^s-1) = (p^s)^{r+1}-1 = p^{s(r+1)}-1$.
\end{proof}

\begin{remark}
Theorem~\ref{thm:closed} is the coefficient-level statement that the local Euler
factor of the Eisenstein $L$-function at $p$ is
$\sum_{r\ge0}\sig_s(p^r)p^{-rw} = (1-p^{-w})^{-1}(1-p^{s-w})^{-1}$, the shadow of
$\sum_{n\ge1}\sig_s(n)n^{-w} = \zeta(w)\zeta(w-s)$.
\end{remark}

\section{M\"obius inversion: recovering pure powers}

The divisor-power sum is the Dirichlet convolution
$\sig_s = \mathbf{1}\star\mathrm{pow}_s$ with $\mathrm{pow}_s(n)=n^s$. Since
$\mathbf 1$ is invertible with inverse $\mu$ ($\mathbf 1\star\mu=\delta$), we may
solve for $\mathrm{pow}_s$.

\begin{theorem}[M\"obius inversion of the divisor-power sum]\label{thm:mob}
For every integer $n\ge 1$,
\[
n^s = \sum_{d\cdot e = n} \mu(d)\,\sig_s(e),
\]
the sum ranging over ordered factorizations $n = d\cdot e$.
\end{theorem}
\begin{proof}
The relation $\sig_s = \mathrm{pow}_s\star\mathbf 1$ inverts, upon convolving with
$\mu$ and using $\mathbf 1\star\mu=\delta$, to $\mathrm{pow}_s = \sig_s\star\mu$,
which is the displayed identity. The single nonelementary ingredient is
$\mathbf 1\star\mu=\delta$ over the divisor lattice.
\end{proof}

\begin{remark}
Theorem~\ref{thm:mob} is the coefficient-level incarnation of dividing the
Eisenstein $L$-function by $\zeta$: from
$\sum\sig_s(n)n^{-w}=\zeta(w)\zeta(w-s)$ one recovers
$\sum n^s n^{-w}=\zeta(w-s)$, and division by $\zeta$ is multiplication by $\mu$
on coefficients.
\end{remark}

\begin{corollary}[M\"obius inversion of the $E_8$ counts]\label{cor:mobE8}
For every $n\ge 1$, $\displaystyle\sum_{d\cdot e = n}\mu(d)\,r(e) = 240\,n^3.$
\end{corollary}
\begin{proof}
Substitute $r(e)=240\,\sig_3(e)$, factor out $240$, and apply
Theorem~\ref{thm:mob} with $s=3$.
\end{proof}

\section{The eigenform boundary}

\begin{theorem}[Quadratic Hecke correction]\label{thm:hecke}
For every prime $p$ and integer $s\ge 0$, $\sig_s(p^2) + p^s = \sig_s(p)^2.$
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:geom}, $\sig_s(p^2)=1+p^s+p^{2s}$ and $\sig_s(p)=1+p^s$, so
$\sig_s(p)^2 = 1+2p^s+p^{2s} = \sig_s(p^2)+p^s$.
\end{proof}

\begin{remark}
The correction $p^s$ is the eigenform defect: for weight $k=s+1$ the Hecke
operators satisfy $T_{p^2}=T_p^2-p^{k-1}$, which on coefficients reads
$\sig_s(p^2)=\sig_s(p)^2-p^s$.
\end{remark}

\begin{theorem}[The eigenform is not a character]\label{thm:strict}
For every prime $p$ and integer $s\ge 0$, $\sig_s(p^2) < \sig_s(p)^2$; thus
$\sig_s$ is multiplicative but strictly fails complete multiplicativity.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:hecke}, $\sig_s(p)^2-\sig_s(p^2)=p^s\ge 1>0$.
\end{proof}

\begin{corollary}[Hecke correction for $E_8$]
For every prime $p$, $240\,r(p^2) + 240^2\,p^3 = r(p)^2.$
\end{corollary}

\begin{corollary}[The $E_8$ counts are not completely multiplicative]
For every prime $p$, $240\,r(p^2) < r(p)^2.$
\end{corollary}

\section{Low-order corroboration}
The first five $E_8$ shell counts are
$r(1)=240,\ r(2)=2160,\ r(3)=6720,\ r(4)=17520,\ r(5)=30240$, matching
$240\,\sig_3(n)$ with $\sig_3(1)=1,\sig_3(2)=9,\sig_3(3)=28,\sig_3(4)=73,\sig_3(5)=126$.
Checks: (closed form) $73\cdot(2^3-1)=511=2^{9}-1$;
(Hecke) $\sig_3(2^2)+2^3=73+8=81=9^2$; (M\"obius, $n=4$)
$\mu(1)\sig_3(4)+\mu(2)\sig_3(2)+\mu(4)\sig_3(1)=73-9+0=64=4^3$.

\section{Discussion and future work}
The identity \eqref{eq:star} and its refinements sit at a crossroads of sphere
packing, modular forms and $L$-functions, and mathematical physics. The three
fingerprints are coefficient-level manifestations of the Euler-product
factorization, the $\zeta$-division, and the Hecke eigenvalue relation for $E_4$.
Future directions include: an explicit weight-$8$ self-convolution law relating
$\sig_7$ to $\sig_3\star\sig_3$; congruence fingerprints locking $r(n)$ modulo
classical moduli to $240\,n^3$; monotonicity of the eigenform defect
$\sig_s(p^2)/\sig_s(p)^2$ in $s$; and a genus-rigidity statement forcing any
even unimodular rank-$8$ lattice satisfying the division-free closed form to be
$E_8$.

\section{Conclusion}
Starting from $r(n)=240\,\sig_3(n)$, we exhibited three independent arithmetic
fingerprints of the $E_8$ coefficient system: a division-free Euler-factor
closed form, a M\"obius inversion recovering pure cubes, and an eigenform defect
$p^s$ certifying strict failure of complete multiplicativity. Together they show
that the census of the densest eight-dimensional packing is, in every measurable
arithmetic respect, the Fourier coefficient system of a weight-$4$ Hecke
eigenform.

