from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n))

def rE8(n: int) -> int:
    return 240 * sigma3(n)

if __name__ == "__main__":
    known = {1: 240, 2: 2160, 3: 6720, 4: 17520, 5: 30240}
    for n, exp in known.items():
        print(n, sigma3(n), rE8(n), exp, rE8(n) == exp)

