def check_closed_form(s: int, primes: Tuple[int, ...], rmax: int) -> None:
    for p in primes:
        for r in range(rmax + 1):
            lhs = sigma(s, p ** r) * (p ** s - 1)
            rhs = p ** (s * (r + 1)) - 1
            assert lhs == rhs, (p, r, lhs, rhs)
            print(f"p={p} r={r}: sigma_{s}(p^r)*(p^{s}-1)={lhs} = p^(s(r+1))-1={rhs}")

if __name__ == "__main__":
    check_closed_form(3, (2, 3, 5, 7), 4)

