        defect = sigma(s, p) ** 2 - sigma(s, p ** 2)
        assert defect == p ** s
        assert sigma(s, p ** 2) < sigma(s, p) ** 2
        print(f"p={p}: sigma_{s}(p)^2 - sigma_{s}(p^2) = {defect} = {p}^{s}")

