from typing import Dict

def factorize(n: int) -> Dict[int, int]:
    """Return the prime factorization of n as {prime: exponent}."""
    factors: Dict[int, int] = {}
    d = 2
    m = n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

def sigma_fast(s: int, n: int) -> int:
    """Compute sigma_s(n) via the division-free closed form on prime powers."""
    result = 1
    for p, a in factorize(n).items():
        ps = p ** s
        if ps == 1:
            local = a + 1
        else:
            local = (p ** (s * (a + 1)) - 1) // (ps - 1)
        result *= local
    return result

