from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def moebius(n: int) -> int:
    if n == 1:
        return 1
    result = 1
    m = n
    p = 2
    while p * p <= m:
        if m % p == 0:
            m //= p
            if m % p == 0:
                return 0
            result = -result
        p += 1
    if m > 1:
        result = -result
    return result

def sigma(s: int, n: int) -> int:
    return sum(d ** s for d in divisors(n))

def moebius_recover_power(s: int, n: int) -> int:
    """Return sum_{d*e=n} mu(d)*sigma_s(e), which equals n^s."""
    return sum(moebius(d) * sigma(s, n // d) for d in divisors(n))

