from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n))

def e8_theta_coefficients(N: int) -> List[int]:
    """Return the first N+1 Fourier coefficients of theta_{E8} = E4:
    [1, 240*sigma_3(1), ..., 240*sigma_3(N)]."""
    coeffs = [1]
    for n in range(1, N + 1):
        coeffs.append(240 * sigma3(n))
    return coeffs
